import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class FloydWarshall {

    private final WeightedGraph graph;

    private FloydWarshall(WeightedGraph graph) {
        this.graph = graph;
    }

    public static FloydWarshall from(int[][] graph) {
        return new FloydWarshall(WeightedGraph.from(graph));
    }

    public static FloydWarshall from(int[][] graph, int unreachableDistance) {
        return new FloydWarshall(WeightedGraph.from(graph, unreachableDistance));
    }

    public static FloydWarshall from(WeightedGraph graph) {
        if (graph == null) {
            throw new IllegalArgumentException("Graph must not be null.");
        }
        return new FloydWarshall(graph);
    }

    public int vertexCount() {
        return graph.vertexCount();
    }

    public Result solve() {
        int[][] distances = graph.adjacencyMatrix();
        int[][] nextHop = new int[graph.vertexCount()][graph.vertexCount()];
        initializeNextHop(distances, nextHop, graph.unreachableDistance());

        int vertices = distances.length;
        int unreachableDistance = graph.unreachableDistance();
        for (int k = 0; k < vertices; k++) {
            for (int i = 0; i < vertices; i++) {
                if (distances[i][k] == unreachableDistance) {
                    continue;
                }

                for (int j = 0; j < vertices; j++) {
                    if (distances[k][j] == unreachableDistance) {
                        continue;
                    }

                    long throughK = (long) distances[i][k] + distances[k][j];
                    if (throughK < distances[i][j]) {
                        distances[i][j] = (int) throughK;
                        nextHop[i][j] = nextHop[i][k];
                    }
                }
            }
        }

        return new Result(distances, nextHop);
    }

    private void initializeNextHop(int[][] adjacencyMatrix, int[][] nextHop, int unreachableDistance) {
        for (int i = 0; i < adjacencyMatrix.length; i++) {
            for (int j = 0; j < adjacencyMatrix.length; j++) {
                nextHop[i][j] = adjacencyMatrix[i][j] == unreachableDistance ? -1 : j;
            }
        }
    }

    public static final class Result {
        private final int[][] distances;
        private final int[][] nextHop;

        private Result(int[][] distances, int[][] nextHop) {
            this.distances = copyMatrix(distances);
            this.nextHop = copyMatrix(nextHop);
        }

        public int vertexCount() {
            return distances.length;
        }

        public int[][] distances() {
            return copyMatrix(distances);
        }

        public int distance(int source, int target) {
            validateVertex(source, distances.length);
            validateVertex(target, distances.length);
            return distances[source][target];
        }

        public List<Integer> path(int source, int target) {
            validateVertex(source, distances.length);
            validateVertex(target, distances.length);

            if (nextHop[source][target] == -1) {
                return Collections.emptyList();
            }

            List<Integer> path = new ArrayList<>();
            int current = source;
            path.add(current);

            while (current != target) {
                current = nextHop[current][target];
                if (current == -1) {
                    return Collections.emptyList();
                }
                path.add(current);
            }

            return Collections.unmodifiableList(path);
        }

        public boolean isReachable(int source, int target) {
            validateVertex(source, distances.length);
            validateVertex(target, distances.length);
            return nextHop[source][target] != -1;
        }

        public boolean hasNegativeCycle() {
            for (int i = 0; i < distances.length; i++) {
                if (distances[i][i] < 0) {
                    return true;
                }
            }
            return false;
        }
    }

    private static void validateVertex(int vertex, int size) {
        if (vertex < 0 || vertex >= size) {
            throw new IllegalArgumentException("Vertex index out of bounds: " + vertex);
        }
    }

    private static int[][] copyMatrix(int[][] source) {
        int[][] copy = new int[source.length][];
        for (int i = 0; i < source.length; i++) {
            copy[i] = source[i].clone();
        }
        return copy;
    }
}

public final class WeightedGraph {

    public static final int DEFAULT_UNREACHABLE_DISTANCE = 100_000_000;

    private final int[][] adjacencyMatrix;
    private final int unreachableDistance;

    private WeightedGraph(int[][] adjacencyMatrix, int unreachableDistance) {
        validateSquareMatrix(adjacencyMatrix);
        validateUnreachableDistance(unreachableDistance);

        this.adjacencyMatrix = copyMatrix(adjacencyMatrix);
        this.unreachableDistance = unreachableDistance;
    }

    public static WeightedGraph from(int[][] adjacencyMatrix) {
        return new WeightedGraph(adjacencyMatrix, DEFAULT_UNREACHABLE_DISTANCE);
    }

    public static WeightedGraph from(int[][] adjacencyMatrix, int unreachableDistance) {
        return new WeightedGraph(adjacencyMatrix, unreachableDistance);
    }

    public int vertexCount() {
        return adjacencyMatrix.length;
    }

    public int unreachableDistance() {
        return unreachableDistance;
    }

    public int distance(int source, int target) {
        validateVertex(source, adjacencyMatrix.length);
        validateVertex(target, adjacencyMatrix.length);
        return adjacencyMatrix[source][target];
    }

    public boolean isUnreachable(int source, int target) {
        return distance(source, target) == unreachableDistance;
    }

    public int[][] adjacencyMatrix() {
        return copyMatrix(adjacencyMatrix);
    }

    private static void validateSquareMatrix(int[][] matrix) {
        if (matrix == null) {
            throw new IllegalArgumentException("Matrix must not be null.");
        }

        for (int i = 0; i < matrix.length; i++) {
            if (matrix[i] == null) {
                throw new IllegalArgumentException("Matrix row " + i + " must not be null.");
            }

            if (matrix[i].length != matrix.length) {
                throw new IllegalArgumentException("Matrix must be square.");
            }
        }
    }

    private static void validateUnreachableDistance(int unreachableDistance) {
        if (unreachableDistance <= 0) {
            throw new IllegalArgumentException("Unreachable distance must be positive.");
        }
    }

    private static void validateVertex(int vertex, int size) {
        if (vertex < 0 || vertex >= size) {
            throw new IllegalArgumentException("Vertex index out of bounds: " + vertex);
        }
    }

    private static int[][] copyMatrix(int[][] source) {
        int[][] copy = new int[source.length][];
        for (int i = 0; i < source.length; i++) {
            copy[i] = source[i].clone();
        }
        return copy;
    }
}

final class FloydWarshallDemo {

    private FloydWarshallDemo() {
        // Demo entrypoint only.
    }

    private static int[][] sampleGraph() {
        return new int[][] {
            {0, 4, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 5, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE},
            {WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 0, 1, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 6},
            {2, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 0, 3, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE},
            {WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 1, 0, 2},
            {1, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, WeightedGraph.DEFAULT_UNREACHABLE_DISTANCE, 4, 0}
        };
    }

    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder line = new StringBuilder();
            for (int value : row) {
                if (line.length() > 0) {
                    line.append(' ');
                }
                line.append(value);
            }
            System.out.println(line);
        }
    }

    public static void main(String[] args) {
        WeightedGraph graph = WeightedGraph.from(sampleGraph());
        FloydWarshall solver = FloydWarshall.from(graph);
        FloydWarshall.Result shortestPaths = solver.solve();
        printMatrix(shortestPaths.distances());
    }
}

